--
-- Name: admin_get_group_predictions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION legacy.admin_get_group_predictions() RETURNS TABLE(user_id uuid, group_preds_count integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'legacy'
    AS $$
  SELECT
    p.user_id,
    COUNT(p.id)::int AS group_preds_count
  FROM predictions p
  INNER JOIN matches m ON m.id = p.match_id
  WHERE m.group_id IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM profiles adm
      WHERE adm.id = auth.uid() AND adm.is_admin = true
    )
  GROUP BY p.user_id;
$$;


--
-- Name: admin_get_match_predictions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION legacy.admin_get_match_predictions(p_match_id uuid) RETURNS TABLE(user_id uuid, display_name text, username text, home_score smallint, away_score smallint, points_earned smallint, total_points bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'legacy', 'auth'
    AS $$
  SELECT
    pr.id,
    pr.display_name::text,
    pr.username::text,
    p.home_score,
    p.away_score,
    COALESCE(p.points_earned, 0)::smallint,
    (
      COALESCE((
        SELECT SUM(p2.points_earned)
        FROM predictions p2
        WHERE p2.user_id = pr.id
          AND p2.points_earned IS NOT NULL
      ), 0) +
      COALESCE((
        SELECT SUM(bp.points_earned)
        FROM bonus_points bp
        WHERE bp.user_id = pr.id
      ), 0)
    )::bigint
  FROM profiles pr
  LEFT JOIN predictions p ON p.user_id = pr.id AND p.match_id = p_match_id
  WHERE pr.is_active = true
    AND EXISTS (
      SELECT 1 FROM profiles adm
      WHERE adm.id = auth.uid() AND adm.is_admin = true
    )
  ORDER BY 7 DESC, 2;
$$;


--
-- Name: admin_get_user_details(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION legacy.admin_get_user_details() RETURNS TABLE(id uuid, email text, predictions_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'legacy', 'auth'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE profiles.id = auth.uid() AND profiles.is_admin = true
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  SELECT
    au.id,
    au.email::text,
    COUNT(p.id)::bigint AS predictions_count
  FROM auth.users au
  LEFT JOIN legacy.predictions p ON p.user_id = au.id
  GROUP BY au.id, au.email;
END;
$$;


