    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    VALUES ('INSERT', NEW.user_id, to_jsonb(NEW));
  ELSIF TG_OP = 'UPDATE' THEN
    VALUES ('UPDATE', NEW.user_id, to_jsonb(OLD), to_jsonb(NEW));
  END IF;
  RETURN NEW;
END;
$$;


