CREATE TABLE legacy.matches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    match_number smallint NOT NULL,
    phase_id uuid NOT NULL,
    group_id uuid,
    home_team_id uuid,
    away_team_id uuid,
    home_slot_label character varying(30),
    away_slot_label character varying(30),
    stadium_id uuid NOT NULL,
    match_datetime timestamp with time zone NOT NULL,
    status character varying(20) DEFAULT 'scheduled'::character varying NOT NULL,
    home_score_90 smallint,
    away_score_90 smallint,
    home_score_et smallint,
    away_score_et smallint,
    home_score_pk smallint,
    away_score_pk smallint,
    winner_team_id uuid,
    CONSTRAINT matches_away_score_90_check CHECK ((away_score_90 >= 0)),
    CONSTRAINT matches_away_score_et_check CHECK ((away_score_et >= 0)),
    CONSTRAINT matches_away_score_pk_check CHECK ((away_score_pk >= 0)),
    CONSTRAINT matches_home_score_90_check CHECK ((home_score_90 >= 0)),
    CONSTRAINT matches_home_score_et_check CHECK ((home_score_et >= 0)),
    CONSTRAINT matches_home_score_pk_check CHECK ((home_score_pk >= 0)),
    CONSTRAINT matches_match_number_check CHECK (((match_number >= 1) AND (match_number <= 104))),
    CONSTRAINT matches_status_check CHECK (((status)::text = ANY ((ARRAY['scheduled'::character varying, 'live'::character varying, 'finished'::character varying])::text[])))
);


--
-- Name: teams; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE legacy.teams (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(100) NOT NULL,
    abbreviation character(3) NOT NULL,
    flag_url character varying(255),
    group_id uuid NOT NULL,
    group_position smallint NOT NULL,
