    placeholder_name character varying(100),
    CONSTRAINT teams_group_position_check CHECK (((group_position >= 1) AND (group_position <= 4)))
);


--
-- Name: group_standings; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW legacy.group_standings AS
 WITH resultados AS (
         SELECT m.group_id,
            m.home_team_id AS team_id,
                CASE
                    WHEN (m.home_score_90 > m.away_score_90) THEN 1
                    ELSE 0
                END AS won,
                CASE
                    WHEN (m.home_score_90 = m.away_score_90) THEN 1
                    ELSE 0
                END AS drawn,
                CASE
                    WHEN (m.home_score_90 < m.away_score_90) THEN 1
                    ELSE 0
                END AS lost,
            (m.home_score_90)::integer AS gf,
            (m.away_score_90)::integer AS gc
           FROM legacy.matches m
          WHERE (((m.status)::text = 'finished'::text) AND (m.group_id IS NOT NULL) AND (m.home_score_90 IS NOT NULL) AND (m.home_team_id IS NOT NULL))
        UNION ALL
         SELECT m.group_id,
            m.away_team_id,
                CASE
                    WHEN (m.away_score_90 > m.home_score_90) THEN 1
                    ELSE 0
                END AS "case",
                CASE
                    WHEN (m.away_score_90 = m.home_score_90) THEN 1
                    ELSE 0
                END AS "case",
                CASE
                    WHEN (m.away_score_90 < m.home_score_90) THEN 1
                    ELSE 0
                END AS "case",
            (m.away_score_90)::integer AS away_score_90,
            (m.home_score_90)::integer AS home_score_90
           FROM legacy.matches m
          WHERE (((m.status)::text = 'finished'::text) AND (m.group_id IS NOT NULL) AND (m.away_score_90 IS NOT NULL) AND (m.away_team_id IS NOT NULL))
        ), stats AS (
         SELECT resultados.group_id,
            resultados.team_id,
            (count(*))::integer AS pj,
            (sum(resultados.won))::integer AS pg,
            (sum(resultados.drawn))::integer AS pe,
            (sum(resultados.lost))::integer AS pp,
            (sum(resultados.gf))::integer AS gf,
            (sum(resultados.gc))::integer AS gc,
            ((sum(resultados.gf) - sum(resultados.gc)))::integer AS gd,
            (((sum(resultados.won) * 3) + sum(resultados.drawn)))::integer AS pts
           FROM resultados
          GROUP BY resultados.group_id, resultados.team_id
        ), ranked AS (
         SELECT t.id AS team_id,
            t.group_id,
            g.name AS group_name,
            g."order" AS group_order,
            t.name AS team_name,
            t.abbreviation AS team_abbreviation,
            t.flag_url AS team_flag_url,
            t.is_confirmed,
            t.placeholder_name,
            COALESCE(s.pj, 0) AS pj,
            COALESCE(s.pg, 0) AS pg,
            COALESCE(s.pe, 0) AS pe,
            COALESCE(s.pp, 0) AS pp,
            COALESCE(s.gf, 0) AS gf,
            COALESCE(s.gc, 0) AS gc,
            COALESCE(s.gd, 0) AS gd,
            COALESCE(s.pts, 0) AS pts,
            (row_number() OVER (PARTITION BY t.group_id ORDER BY COALESCE(s.pts, 0) DESC, COALESCE(s.gd, 0) DESC, COALESCE(s.gf, 0) DESC, t.name))::integer AS auto_position,
            gpo."position" AS override_position
           FROM (((legacy.teams t
             JOIN legacy.groups g ON ((g.id = t.group_id)))
             LEFT JOIN stats s ON (((s.team_id = t.id) AND (s.group_id = t.group_id))))
             LEFT JOIN legacy.group_position_overrides gpo ON ((gpo.team_id = t.id)))
        )
 SELECT team_id,
    group_id,
    group_name,
    group_order,
    team_name,
    team_abbreviation,
    team_flag_url,
    is_confirmed,
    placeholder_name,
    pj,
    pg,
    pe,
    pp,
    gf,
    gc,
    gd,
    pts,
    COALESCE(override_position, auto_position) AS "position",
    (override_position IS NOT NULL) AS has_override
   FROM ranked
  ORDER BY group_order, COALESCE(override_position, auto_position);


--
-- Name: best_third_ranking; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW legacy.best_third_ranking AS
 WITH auto_ranked AS (
         SELECT gs.team_id,
            gs.group_id,
            gs.group_name,
            gs.team_name,
            gs.team_flag_url,
            gs.is_confirmed,
            gs.placeholder_name,
            gs.pj,
            gs.pg,
            gs.pe,
            gs.pp,
            gs.gf,
            gs.gc,
            gs.gd,
            gs.pts,
            (row_number() OVER (ORDER BY gs.pts DESC, gs.gd DESC, gs.gf DESC, gs.team_name))::integer AS auto_rank,
            btro.rank AS override_rank
           FROM (legacy.group_standings gs
             LEFT JOIN legacy.best_third_rank_overrides btro ON ((btro.team_id = gs.team_id)))
          WHERE (gs."position" = 3)
        )
 SELECT team_id,
    group_id,
    group_name,
    team_name,
    team_flag_url,
    is_confirmed,
    placeholder_name,
    pj,
    pg,
    pe,
    pp,
    gf,
    gc,
    gd,
    pts,
    COALESCE(override_rank, auto_rank) AS rank,
    (override_rank IS NOT NULL) AS has_override
   FROM auto_ranked
  ORDER BY COALESCE(override_rank, auto_rank);


