    is_loader boolean DEFAULT false NOT NULL
);


--
-- Name: leaderboard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW legacy.leaderboard AS
 SELECT p.id AS user_id,
    p.username,
    p.display_name,
    p.avatar_url,
    ((COALESCE(sum(pr.points_earned), (0)::bigint) + COALESCE(( SELECT sum(bp.points_earned) AS sum
           FROM legacy.bonus_points bp
          WHERE (bp.user_id = p.id)), (0)::bigint)))::integer AS total_points,
    (count(pr.id))::integer AS predictions_count,
    (count(
        CASE
            WHEN (((m.status)::text = 'finished'::text) AND (pr.home_score = m.home_score_90) AND (pr.away_score = m.away_score_90)) THEN 1
            ELSE NULL::integer
        END))::integer AS exact_scores,
    (count(
        CASE
            WHEN (((m.status)::text = 'finished'::text) AND (COALESCE((pr.points_earned)::integer, 0) > 0)) THEN 1
            ELSE NULL::integer
        END))::integer AS correct_predictions,
    (rank() OVER (ORDER BY (COALESCE(sum(pr.points_earned), (0)::bigint) + COALESCE(( SELECT sum(bp2.points_earned) AS sum
           FROM legacy.bonus_points bp2
          WHERE (bp2.user_id = p.id)), (0)::bigint)) DESC))::integer AS rank
   FROM ((legacy.profiles p
     LEFT JOIN legacy.predictions pr ON ((pr.user_id = p.id)))
     LEFT JOIN legacy.matches m ON ((m.id = pr.match_id)))
  WHERE (p.is_active = true)
  GROUP BY p.id, p.username, p.display_name, p.avatar_url;


