--
-- Name: subgrupo_ranking; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW legacy.subgrupo_ranking WITH (security_invoker='true') AS
 SELECT sm.subgrupo_id,
    sm.user_id,
    lb.total_points,
    lb.rank AS global_rank,
    lb.predictions_count,
    lb.exact_scores,
    lb.display_name,
    lb.username,
    lb.avatar_url,
    rank() OVER (PARTITION BY sm.subgrupo_id ORDER BY lb.total_points DESC) AS subgrupo_rank
   FROM (legacy.subgrupo_members sm
     JOIN legacy.leaderboard lb ON ((lb.user_id = sm.user_id)));


