-- Name: matches Admin or loader can update matches; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admin or loader can update matches" ON legacy.matches FOR UPDATE USING ((EXISTS ( SELECT 1
   FROM legacy.profiles
  WHERE ((profiles.id = auth.uid()) AND ((profiles.is_admin = true) OR (profiles.is_loader = true))))));


--
-- Name: email_queue admin_all_email_queue; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY admin_all_email_queue ON legacy.email_queue TO authenticated USING ((EXISTS ( SELECT 1
   FROM legacy.profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.is_admin = true))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM legacy.profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.is_admin = true)))));


